"""Report card v2 (weights): updates the `school` + `zis` blueprints, installs on staging via the engine's own
rendering, renders sample PDFs for Dennis Otieno, Term 3 2025-26. Run inside the backend container from sites/."""
import os, frappe
REC = '{% raw %}[\n {\n  "doctype": "Print Format",\n  "name": "ZanaSchools Report Card",\n  "doc_type": "Student",\n  "module": "Education",\n  "standard": "No",\n  "custom_format": 1,\n  "print_format_type": "Jinja",\n  "disabled": 0,\n  "margin_top": 12,\n  "margin_bottom": 12,\n  "html": "{%- set ns = namespace(term=frappe.form_dict.get(\\"term\\") or \\"\\", best=None) -%}\\n{%- if not ns.term -%}{%- for r in frappe.get_all(\\"Assessment Result\\", filters={\\"student\\": doc.name, \\"docstatus\\": 1}, fields=[\\"academic_term\\"], distinct=True) -%}{%- set sd = frappe.db.get_value(\\"Academic Term\\", r.academic_term, \\"term_start_date\\") -%}{%- if sd and (ns.best is none or sd > ns.best) -%}{%- set ns.best = sd -%}{%- set ns.term = r.academic_term -%}{%- endif -%}{%- endfor -%}{%- endif -%}\\n{%- set t = frappe.db.get_value(\\"Academic Term\\", ns.term, [\\"academic_year\\", \\"term_name\\", \\"term_start_date\\", \\"term_end_date\\"], as_dict=True) if ns.term else None -%}\\n{%- set pe = frappe.db.get_value(\\"Program Enrollment\\", {\\"student\\": doc.name, \\"academic_year\\": t.academic_year if t else \\"\\", \\"docstatus\\": 1}, [\\"program\\", \\"student_batch_name\\", \\"school_house\\"], as_dict=True) if t else None -%}\\n{%- set guardians = frappe.get_all(\\"Student Guardian\\", filters={\\"parent\\": doc.name, \\"parenttype\\": \\"Student\\"}, fields=[\\"guardian_name\\", \\"relation\\"], order_by=\\"idx\\") -%}\\n{%- set results = frappe.get_all(\\"Assessment Result\\", filters={\\"student\\": doc.name, \\"academic_term\\": ns.term, \\"docstatus\\": 1}, fields=[\\"name\\", \\"course\\", \\"grading_scale\\", \\"comment\\"], order_by=\\"course\\") if ns.term else [] -%}\\n{%- set rnames = results | map(attribute=\\"name\\") | list -%}\\n{%- set details = frappe.get_all(\\"Assessment Result Detail\\", filters={\\"parent\\": [\\"in\\", rnames]}, fields=[\\"parent\\", \\"assessment_criteria\\", \\"score\\", \\"maximum_score\\"]) if rnames else [] -%}\\n{%- set present = details | map(attribute=\\"assessment_criteria\\") | unique | list -%}\\n{%- set cols = [] -%}\\n{%- for c in [\\"Coursework\\", \\"Class Test\\", \\"Exam\\"] + present -%}{%- if c in present and c not in cols -%}{%- set _ = cols.append(c) -%}{%- endif -%}{%- endfor -%}\\n{%- set courses = results | map(attribute=\\"course\\") | unique | list -%}\\n{%- set scale_name = results[0].grading_scale if results else None -%}\\n{%- set intervals = frappe.get_all(\\"Grading Scale Interval\\", filters={\\"parent\\": scale_name}, fields=[\\"grade_code\\", \\"threshold\\", \\"grade_description\\"], order_by=\\"threshold desc\\") if scale_name else [] -%}\\n{%- macro grade_for(pct) -%}{%- set g = namespace(v=\\"\\") -%}{%- for i in intervals -%}{%- if not g.v and pct >= i.threshold -%}{%- set g.v = i.grade_code -%}{%- endif -%}{%- endfor -%}{{ g.v }}{%- endmacro -%}\\n{%- set tot = namespace(s=0, m=0, n=0) -%}\\n{%- set default_weights = {{% endraw %}{% for k, v in ((vars.report_card or {}).get(\'weights\') or {}).items() %}\'{{ k }}\': {{ v }}{% if not loop.last %}, {% endif %}{% endfor %}{% raw %}} -%}\\n{%- set cwc = {} -%}\\n{%- macro course_weights(course) -%}{%- if course not in cwc -%}{%- set w = {} -%}{%- for r in frappe.get_all(\\"Course Assessment Criteria\\", filters={\\"parent\\": course}, fields=[\\"assessment_criteria\\", \\"weightage\\"]) -%}{%- if r.weightage -%}{%- set _ = w.update({r.assessment_criteria: r.weightage}) -%}{%- endif -%}{%- endfor -%}{%- set _ = cwc.update({course: w}) -%}{%- endif -%}{%- endmacro -%}\\n{%- set basis = namespace(weighted=0, marks=0) -%}\\n{%- macro course_pct(cd, course) -%}{{- course_weights(course) -}}{%- set wsrc = cwc[course] or default_weights -%}{%- set ws = namespace(sum=0, wt=0, ok=1, s=0, m=0) -%}{%- for d in cd -%}{%- set ws.s = ws.s + d.score -%}{%- set ws.m = ws.m + d.maximum_score -%}{%- set w = wsrc.get(d.assessment_criteria) if wsrc else None -%}{%- if w and d.maximum_score -%}{%- set ws.sum = ws.sum + (d.score * 100.0 / d.maximum_score) * w -%}{%- set ws.wt = ws.wt + w -%}{%- else -%}{%- set ws.ok = 0 -%}{%- endif -%}{%- endfor -%}{%- if wsrc and ws.ok and ws.wt -%}{{ ws.sum / ws.wt }}|W{%- else -%}{{ (ws.s * 100.0 / ws.m) if ws.m else 0 }}|M{%- endif -%}{%- endmacro -%}\\n{%- set show_position = {% endraw %}{{ \'true\' if (vars.report_card or {}).get(\'show_position\') else \'false\' }}{% raw %} -%}\\n{%- set pos = namespace(rank=0, size=0) -%}\\n{%- if show_position and pe and t -%}\\n  {%- set mates = frappe.get_all(\\"Program Enrollment\\", filters={\\"program\\": pe.program, \\"student_batch_name\\": pe.student_batch_name, \\"academic_year\\": t.academic_year, \\"docstatus\\": 1}, pluck=\\"student\\") -%}\\n  {%- set mres = frappe.get_all(\\"Assessment Result\\", filters={\\"student\\": [\\"in\\", mates], \\"academic_term\\": ns.term, \\"docstatus\\": 1}, fields=[\\"name\\", \\"student\\", \\"course\\"]) -%}\\n  {%- set mdet = frappe.get_all(\\"Assessment Result Detail\\", filters={\\"parent\\": [\\"in\\", mres | map(attribute=\\"name\\") | list]}, fields=[\\"parent\\", \\"assessment_criteria\\", \\"score\\", \\"maximum_score\\"]) if mres else [] -%}\\n  {%- set avgs = {} -%}\\n  {%- for st in mres | map(attribute=\\"student\\") | unique -%}\\n    {%- set acc = namespace(s=0, n=0) -%}\\n    {%- for course in mres | selectattr(\\"student\\", \\"equalto\\", st) | map(attribute=\\"course\\") | unique -%}\\n      {%- set rn2 = mres | selectattr(\\"student\\", \\"equalto\\", st) | selectattr(\\"course\\", \\"equalto\\", course) | map(attribute=\\"name\\") | list -%}\\n      {%- set acc.s = acc.s + (course_pct(mdet | selectattr(\\"parent\\", \\"in\\", rn2) | list, course).split(\\"|\\")[0] | float) -%}{%- set acc.n = acc.n + 1 -%}\\n    {%- endfor -%}\\n    {%- set _ = avgs.update({st: (acc.s / acc.n) if acc.n else 0}) -%}\\n  {%- endfor -%}\\n  {%- set my = avgs.get(doc.name, 0) -%}\\n  {%- set pos.size = avgs | length -%}{%- set pos.rank = 1 -%}\\n  {%- for s, v in avgs.items() -%}{%- if v > my -%}{%- set pos.rank = pos.rank + 1 -%}{%- endif -%}{%- endfor -%}\\n{%- endif -%}\\n{%- set att = frappe.get_all(\\"Student Attendance\\", filters={\\"student\\": doc.name, \\"docstatus\\": 1, \\"date\\": [\\"between\\", [t.term_start_date, t.term_end_date]]}, fields=[\\"status\\"]) if t else [] -%}\\n{%- set a_present = att | selectattr(\\"status\\", \\"equalto\\", \\"Present\\") | list | length -%}\\n{%- set a_absent = att | selectattr(\\"status\\", \\"equalto\\", \\"Absent\\") | list | length -%}\\n{%- set a_leave = att | selectattr(\\"status\\", \\"equalto\\", \\"Leave\\") | list | length -%}\\n{%- set sg = frappe.get_all(\\"Student Group\\", filters={\\"program\\": pe.program, \\"batch\\": pe.student_batch_name, \\"academic_year\\": t.academic_year, \\"group_based_on\\": \\"Batch\\"}, fields=[\\"name\\"], limit=1) if pe and t else [] -%}\\n{%- set tutor = frappe.get_all(\\"Student Group Instructor\\", filters={\\"parent\\": sg[0].name}, fields=[\\"instructor_name\\"], limit=1) if sg else [] -%}\\n<style>\\n  .rc { font-family: \\"DejaVu Sans\\", Arial, sans-serif; font-size: 10px; color: #1d2b27; }\\n  .rc h1 { font-size: 19px; letter-spacing: 3px; color: #1F5D4C; margin: 2px 0 0 0; }\\n  .rc .muted { color: #6b7a75; }\\n  .rc .lbl { font-size: 8px; text-transform: uppercase; letter-spacing: 1px; color: #6b7a75; }\\n  .rc table.grid { width: 100%; border-collapse: collapse; }\\n  .rc .box { border: 1px solid #d9e1de; padding: 9px 11px; vertical-align: top; }\\n  .rc table.res th { background: #1F5D4C; color: #fff; padding: 6px 7px; font-size: 8.5px; letter-spacing: 1px; text-align: center; }\\n  .rc table.res th.l { text-align: left; }\\n  .rc table.res td { padding: 6px 7px; border-bottom: 1px solid #e3e8e6; text-align: center; }\\n  .rc table.res td.l { text-align: left; }\\n  .rc table.res tr:nth-child(even) td { background: #f6f8f7; }\\n  .rc .grade { font-weight: bold; color: #1F5D4C; }\\n  .rc .big { font-size: 17px; font-weight: bold; color: #1F5D4C; }\\n  .rc .sign { border-bottom: 1px solid #9aa8a3; height: 34px; }\\n</style>\\n{% if letter_head and not no_letterhead %}<div style=\\"margin-bottom:10px\\">{{ letter_head }}</div>{% endif %}\\n<div class=\\"rc\\">\\n  <table class=\\"grid\\"><tr>\\n    <td><h1>END OF TERM REPORT</h1><div class=\\"muted\\">{{ (t.term_name if t else \\"\\") }} &middot; Academic year {{ (t.academic_year if t else \\"\\") }}</div></td>\\n    {% if show_position and pos.size %}<td style=\\"text-align:right;vertical-align:bottom\\"><span class=\\"lbl\\">Position in class</span><br><span class=\\"big\\">{{ pos.rank }}</span> <span class=\\"muted\\">of {{ pos.size }}</span></td>{% endif %}\\n  </tr></table>\\n\\n  <table class=\\"grid\\" style=\\"margin-top:12px\\"><tr>\\n    <td class=\\"box\\" style=\\"width:58%\\">\\n      <div class=\\"lbl\\">Student</div>\\n      <div style=\\"font-size:13px;font-weight:bold;margin:2px 0\\">{{ doc.student_name }}</div>\\n      <div class=\\"muted\\">Student ID: {{ doc.name }}{% if pe %} &middot; Class: {{ pe.program }}{{ pe.student_batch_name or \\"\\" }}{% if pe.school_house %} &middot; House: {{ pe.school_house }}{% endif %}{% endif %}</div>\\n      {% if guardians %}<div style=\\"margin-top:5px\\"><span class=\\"lbl\\">Parent / Guardian</span><br>{% for g in guardians %}{{ g.guardian_name }} <span class=\\"muted\\">({{ g.relation }})</span>{% if not loop.last %}, {% endif %}{% endfor %}</div>{% endif %}\\n    </td>\\n    <td style=\\"width:2%\\"></td>\\n    <td class=\\"box\\">\\n      <div class=\\"lbl\\">Attendance this term</div>\\n      {% set a_total = a_present + a_absent + a_leave %}\\n      <div style=\\"margin-top:3px\\"><span class=\\"big\\">{{ ((a_present * 100.0 / a_total) | round(1)) if a_total else \\"-\\" }}%</span></div>\\n      <div class=\\"muted\\">Present {{ a_present }} &middot; Absent {{ a_absent }} &middot; Leave {{ a_leave }} &middot; of {{ a_total }} days</div>\\n      {% if tutor %}<div style=\\"margin-top:5px\\"><span class=\\"lbl\\">Form tutor</span><br>{{ tutor[0].instructor_name }}</div>{% endif %}\\n    </td>\\n  </tr></table>\\n\\n  <table class=\\"grid res\\" style=\\"margin-top:14px\\">\\n    <tr><th class=\\"l\\">Subject</th>{% for c in cols %}<th>{{ c }}</th>{% endfor %}<th>Overall %</th><th>Grade</th><th class=\\"l\\" style=\\"width:32%\\">Teacher\'s comment</th></tr>\\n    {% for course in courses %}\\n      {%- set rn = results | selectattr(\\"course\\", \\"equalto\\", course) | map(attribute=\\"name\\") | list -%}\\n      {%- set cd = details | selectattr(\\"parent\\", \\"in\\", rn) | list -%}\\n      {%- set cp = course_pct(cd, course).split(\\"|\\") -%}\\n      {%- set pct = cp[0] | float -%}\\n      {%- if cp[1] == \\"W\\" -%}{%- set basis.weighted = 1 -%}{%- else -%}{%- set basis.marks = 1 -%}{%- endif -%}\\n      {%- set tot.s = tot.s + pct -%}{%- set tot.n = tot.n + 1 -%}\\n      {%- set comment = results | selectattr(\\"course\\", \\"equalto\\", course) | selectattr(\\"comment\\") | map(attribute=\\"comment\\") | list -%}\\n      <tr><td class=\\"l\\"><b>{{ course }}</b></td>\\n        {% for c in cols %}{%- set hit = cd | selectattr(\\"assessment_criteria\\", \\"equalto\\", c) | list -%}\\n          <td>{% if hit %}{{ hit[0].score | round(1) }}<span class=\\"muted\\">/{{ hit[0].maximum_score | int }}</span>{% else %}<span class=\\"muted\\">&ndash;</span>{% endif %}</td>{% endfor %}\\n        <td>{{ pct | round(1) }}</td><td class=\\"grade\\">{{ grade_for(pct) }}</td>\\n        <td class=\\"l muted\\">{{ comment[-1] if comment else \\"\\" }}</td></tr>\\n    {% endfor %}\\n    {% if not courses %}<tr><td class=\\"l muted\\" colspan=\\"{{ cols | length + 4 }}\\">No assessment results recorded for this term yet.</td></tr>{% endif %}\\n  </table>\\n\\n  {% if courses %}\\n  <table class=\\"grid\\" style=\\"margin-top:10px\\"><tr>\\n    <td class=\\"box\\" style=\\"width:30%\\"><div class=\\"lbl\\">Overall average</div><span class=\\"big\\">{{ (tot.s / tot.n) | round(1) }}%</span> <span class=\\"grade\\">{{ grade_for(tot.s / tot.n) }}</span></td>\\n    <td style=\\"width:2%\\"></td>\\n    <td class=\\"box\\"><div class=\\"lbl\\">Grading key</div>\\n      {% for i in intervals %}<b>{{ i.grade_code }}</b> {{ i.threshold | int }}%+{% if i.grade_description %} {{ i.grade_description }}{% endif %}{% if not loop.last %} &middot; {% endif %}{% endfor %}</td>\\n  </tr></table>\\n  <div class=\\"muted\\" style=\\"margin-top:5px;font-size:8.5px\\">Overall % per subject:\\n    {% if basis.weighted %}weighted by assessment{% if default_weights %} ({% for k, v in default_weights.items() %}{{ k }} {{ v }}{% if not loop.last %}, {% endif %}{% endfor %}, unless a subject sets its own){% endif %}{% if basis.marks %}; some subjects by total marks{% endif %}{% else %}by total marks across assessments{% endif %}.\\n    Weights rebalance when an assessment is not taken.</div>\\n  {% endif %}\\n\\n  <table class=\\"grid\\" style=\\"margin-top:14px\\"><tr>\\n    <td class=\\"box\\" style=\\"width:49%\\"><div class=\\"lbl\\">Form tutor\'s remark</div><div class=\\"sign\\"></div><div class=\\"muted\\" style=\\"margin-top:4px\\">Signature &amp; date</div></td>\\n    <td style=\\"width:2%\\"></td>\\n    <td class=\\"box\\"><div class=\\"lbl\\">Principal\'s remark</div><div class=\\"sign\\"></div><div class=\\"muted\\" style=\\"margin-top:4px\\">Signature &amp; date</div></td>\\n  </tr></table>\\n</div>\\n"\n }\n]{% endraw %}'
SITE = "zanaschools-staging.zanaverse.com"
STUDENT, TERM = "EDU-STU-2026-00011", "2025-2026 (Term 3)"
frappe.init(site=SITE, sites_path="."); frappe.connect(); frappe.set_user("Administrator")
root = frappe.get_app_path("zanaverse_blueprints", "blueprints")
school, zis = os.path.join(root, "school"), os.path.join(root, "zis")

open(os.path.join(school, "print_format_report_card.json"), "w", encoding="utf-8").write(REC)
y = open(os.path.join(school, "blueprint.yaml"), encoding="utf-8").read()
if "print_format_report_card.json" not in y:
    y = y.replace("  - file: property_setter.json",
                  "  - file: print_format_report_card.json  # END OF TERM REPORT on Student (?term=... in the print URL; default latest term)\n  - file: property_setter.json")
if "\nvars:" not in y:
    y = y.replace("\nrecords:", "\nvars:\n  report_card:\n    show_position: false   # per school: true shows position in class\n\nrecords:", 1)
if "    weights:" not in y:
    y = y.replace("    show_position: false", "    show_position: false\n    weights: {}            # per school default, e.g. {Coursework: 20, Class Test: 20, Exam: 60}; a subject's own weightage (Course form) wins; empty = by total marks", 1)
open(os.path.join(school, "blueprint.yaml"), "w", encoding="utf-8").write(y)
z = open(os.path.join(zis, "blueprint.yaml"), encoding="utf-8").read()
if "report_card:" not in z:
    z = z.replace('  mobile_money: {paybill: "400 500"}', '  mobile_money: {paybill: "400 500"}\n  report_card: {weights: {Coursework: 20, Class Test: 20, Exam: 60}}   # CA 40 / Exam 60', 1)
open(os.path.join(zis, "blueprint.yaml"), "w", encoding="utf-8").write(z)
print("blueprints updated: school (record, vars) + zis (weights 20/20/60)")

from zanaverse_onboarding import blueprint_apply as ba, blueprint_extras as x
from frappe.core.doctype.data_import.data_import import import_doc
def install(show_position):
    chain = ba._chain("zis"); company = next(b.get("company") for _, b in reversed(chain) if b.get("company"))
    x.build_context(chain, company)
    x.CONTEXT["vars"].setdefault("report_card", {})["show_position"] = show_position
    import_doc(x.render_record_file(school, "print_format_report_card.json")); frappe.db.commit()
    return x.CONTEXT["vars"]["report_card"]

frappe.form_dict.term = TERM
for flag, fname in ((True, "sample-report-card-with-position.pdf"), (False, "sample-report-card.pdf")):
    rc = install(flag)
    try:
        pdf = frappe.get_print("Student", STUDENT, print_format="ZanaSchools Report Card", as_pdf=True)
        open(frappe.get_site_path("public", "files", fname), "wb").write(pdf)
        print(f"position {'on ' if flag else 'off'} | weights {rc.get('weights')}: PDF OK ({len(pdf):,} bytes) -> https://{SITE}/files/{fname}")
    except Exception:
        print(f"position {'on ' if flag else 'off'}: FAILED\n{frappe.get_traceback()[-1200:]}")
frappe.destroy()
